/** Revision-private bounded envelope placement; not production seed derivation. */
import { createHash } from 'node:crypto';

export const PLACEMENT_REVISION = 'issue-169-placement-v1';
export const GAP_RAD = 0.05;
export const EXTENSION_RAD = 0.02;
export const MAX_ATTEMPTS = 64;
export const DIRECTIONS_PER_OWNER = 128;
export const dot = (a, b) => a.reduce((sum, value, i) => sum + value * b[i], 0);
export const angle = (a, b) => Math.acos(Math.max(-1, Math.min(1, dot(a, b))));
const compareId = (a, b) => (a.id < b.id ? -1 : a.id > b.id ? 1 : 0);
const cross = (a, b) => [
  a[1] * b[2] - a[2] * b[1],
  a[2] * b[0] - a[0] * b[2],
  a[0] * b[1] - a[1] * b[0],
];
const normalize = (point) => point.map((value) => value / Math.hypot(...point));

/** The whole key is JSON encoded, avoiding ambiguous owner/scope separators. */
function stream(seed, ownerId, attempt, scope) {
  let counter = 0;
  return () =>
    createHash('sha256')
      .update(
        JSON.stringify([PLACEMENT_REVISION, String(seed), ownerId, attempt, scope, counter++]),
      )
      .digest()
      .readUInt32BE(0) /
    2 ** 32;
}

function direction(random) {
  const z = 2 * random() - 1,
    azimuth = 2 * Math.PI * random(),
    radius = Math.sqrt(1 - z * z);
  return [radius * Math.cos(azimuth), radius * Math.sin(azimuth), z];
}

function frame(center, orientation) {
  const east0 = normalize(cross(Math.abs(center[2]) < 0.9 ? [0, 0, 1] : [1, 0, 0], center)),
    north0 = cross(center, east0),
    east = east0.map(
      (value, index) => value * Math.cos(orientation) + north0[index] * Math.sin(orientation),
    );
  return { center, east, north: cross(center, east) };
}

/** No radius change, quota transfer, owner removal, backtracking, or hidden retry. */
export function placeOwners(owners, seed) {
  const failure = (code, details = {}) => ({
    ok: false,
    owners: [],
    failures: [{ code, ...details }],
    attempts: 0,
    candidateCount: 0,
  });
  if (
    !Array.isArray(owners) ||
    owners.length < 1 ||
    owners.length > 8 ||
    owners.some(
      (owner) =>
        owner === null ||
        typeof owner !== 'object' ||
        typeof owner.id !== 'string' ||
        owner.id.length === 0 ||
        !Number.isFinite(owner.radius) ||
        owner.radius <= 0 ||
        owner.radius + EXTENSION_RAD >= Math.PI,
    ) ||
    new Set(owners.map(({ id }) => id)).size !== owners.length
  )
    return failure('placement.invalid-input');

  const ordered = [...owners].sort((a, b) => b.radius - a.radius || compareId(a, b));
  for (let i = 0; i < ordered.length; i++)
    for (let j = i + 1; j < ordered.length; j++) {
      const requiredDistance = ordered[i].radius + ordered[j].radius + GAP_RAD;
      if (requiredDistance > Math.PI)
        return failure('placement.pair-capacity', {
          ownerIds: [ordered[i].id, ordered[j].id],
          requiredDistance,
          maximumDistance: Math.PI,
          proof: 'pair-caps-cannot-fit',
        });
    }

  const failures = [];
  let candidateCount = 0;
  for (let attempt = 0; attempt < MAX_ATTEMPTS; attempt++) {
    const placed = [];
    for (const owner of ordered) {
      const random = stream(seed, owner.id, attempt, 'center-directions');
      let selected;
      for (let candidate = 0; candidate < DIRECTIONS_PER_OWNER; candidate++) {
        const center = direction(random);
        candidateCount++;
        if (
          placed.every(
            (other) => angle(center, other.center) >= owner.radius + other.radius + GAP_RAD,
          )
        ) {
          selected = {
            ...owner,
            ...frame(center, 2 * Math.PI * stream(seed, owner.id, attempt, 'orientation')()),
          };
          break;
        }
      }
      if (selected === undefined) {
        failures.push({
          code: 'placement.attempt-exhausted',
          attempt: attempt + 1,
          ownerId: owner.id,
          directionCount: DIRECTIONS_PER_OWNER,
        });
        break;
      }
      placed.push(selected);
    }
    if (placed.length === owners.length)
      return {
        ok: true,
        owners: placed.sort(compareId),
        failures,
        attempts: attempt + 1,
        candidateCount,
      };
  }
  failures.push({ code: 'placement.search-exhausted', proof: 'search-only-not-infeasibility' });
  return { ok: false, owners: [], failures, attempts: MAX_ATTEMPTS, candidateCount };
}

field.mjs:
/** Fixed-zero continuous field for certified, post-scaled experimental land polygons. */
import { forwardLambert, signedDistance } from './geometry.mjs';
import { angle, dot, EXTENSION_RAD } from './placement.mjs';

export const FIELD_REVISION = 'issue-169-fixed-zero-v1';
export const TICKS = 1_000_000;

/** Geometry and separation certificates are prerequisites, never repaired by this evaluator. */
export function createPlacedField(owners, input) {
  if (owners.length === 0) throw new RangeError('A placed field requires at least one owner.');
  const prepared = owners.map((owner) => {
    if (!(owner.radius > 0 && owner.radius + EXTENSION_RAD < Math.PI))
      throw new RangeError('The negative extension must stay away from the chart antipode.');
    return {
      owner,
      polygons: [
        owner.candidate.bodyBoundary,
        ...owner.candidate.islands.map(({ polygon }) => polygon),
      ],
    };
  });

  function evaluateWithOwner(point) {
    let value = -Infinity,
      selectedOwner = -1,
      guarded = false;
    prepared.forEach(({ owner, polygons }, index) => {
      const distance = angle(owner.center, point),
        guard = owner.radius - distance;
      let candidate = guard;
      if (distance < owner.radius + EXTENSION_RAD) {
        const local = [dot(owner.east, point), dot(owner.north, point), dot(owner.center, point)],
          h = signedDistance(forwardLambert(local), polygons);
        candidate = Math.min(Math.max(h, -EXTENSION_RAD), guard);
      }
      if (!Number.isFinite(candidate))
        throw new RangeError('The field produced a non-finite scalar.');
      // Stable owner order supplies the tie rule; never omit negative candidates.
      if (candidate > value) {
        value = candidate;
        selectedOwner = index;
        guarded = guard > 0;
      }
    });
    return { value, owner: selectedOwner, guarded };
  }

  return {
    revision: FIELD_REVISION,
    owners,
    input,
    evaluate: (point) => evaluateWithOwner(point).value,
    raw: (point) => {
      const result = evaluateWithOwner(point);
      return { ...result, value: Math.round(result.value * TICKS) };
    },
  };
}

run.mjs:
/** Investigation-only local gate and immutable fixed-input comparison receipts. */
import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { mkdir, readFile, writeFile } from 'node:fs/promises';
import { join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

import { format } from 'prettier';

import { landFraction, sampleGrid } from '../issue-164/morphology.mjs';
import { png, smoke } from '../issue-164/render-comparison.mjs';
import { inputs } from '../issue-165/run.mjs';
import { createPlacedField } from './field.mjs';
import { placeOwners } from './placement.mjs';
import { constructOwners } from './templates.mjs';

const HERE = fileURLToPath(new URL('.', import.meta.url));
const hash = (value) => createHash('sha256').update(value).digest('hex');
const json = async (path, value) =>
  writeFile(path, await format(JSON.stringify(value), { parser: 'json', printWidth: 100 }));
export function gridBytes(grid) {
  const bytes = Buffer.alloc(grid.values.length * 5);
  for (let i = 0; i < grid.values.length; i++) {
    bytes.writeInt32BE(grid.values[i], i * 5);
    bytes.writeInt8(grid.owners[i], i * 5 + 4);
  }
  return bytes;
}
export function coverage(grid, owners, input) {
  const water = 100 * (1 - landFraction(grid, 0));
  const areas = owners.map(() => 0);
  let total = 0;
  for (let y = 0; y <= grid.height; y++) {
    const weight = grid.weights[y];
    total += grid.width * weight;
    for (let x = 0; x < grid.width; x++) {
      const i = y * grid.width + x;
      if (grid.values[i] > 0) areas[grid.owners[i]] += weight;
    }
  }
  return {
    waterPercent: water,
    errorPercentagePoints: water - input.controls.targetWaterCoveragePercent,
    owners: owners.map((owner, i) => ({
      id: owner.id,
      quota: owner.quota,
      realizedSphereFraction: areas[i] / total,
      errorPercentagePoints: 100 * (areas[i] / total - owner.quota),
    })),
  };
}
export async function localGate() {
  const [input] = await inputs();
  const construction = constructOwners(input);
  const repeat = constructOwners(input);
  assert.deepEqual(construction, repeat);
  return {
    input,
    ...construction,
    exactRepeat: true,
    completePrimaryPassed: construction.owners.some(
      (owner) => owner.candidate.primary && owner.certificate.ok,
    ),
  };
}
export function render(input) {
  const construction = constructOwners(input);
  if (!construction.ok)
    return {
      report: { input, stage: 'construction-failed', numericEligible: false, construction },
    };
  const placement = placeOwners(construction.owners, input.seed);
  if (!placement.ok)
    return {
      report: { input, stage: 'placement-failed', numericEligible: false, construction, placement },
    };
  const field = createPlacedField(placement.owners, input);
  const preview = sampleGrid(field, 400, 200),
    full = sampleGrid(field, 1600, 800);
  const previewCoverage = coverage(preview, placement.owners, input);
  const fullCoverage = coverage(full, placement.owners, input);
  const mask = Uint8Array.from(full.values.subarray(0, 1600 * 800), (v) => Number(v > 0));
  const halfMask = new Uint8Array(800 * 400);
  for (let y = 0; y < 400; y++)
    for (let x = 0; x < 800; x++) halfMask[y * 800 + x] = mask[y * 2 * 1600 + x * 2];
  const nativeImage = png(mask, 1600, 800),
    halfImage = png(halfMask, 800, 400);
  const numericEligible =
    Math.abs(previewCoverage.errorPercentagePoints) <= 0.25 &&
    Math.abs(fullCoverage.errorPercentagePoints) <= 0.25 &&
    previewCoverage.owners.every(
      (owner) =>
        Math.abs(owner.errorPercentagePoints) <= 0.25 / input.controls.continentCountIntent,
    );
  return {
    nativeImage,
    halfImage,
    report: {
      input,
      stage: numericEligible ? 'numeric-gates-passed' : 'coverage-failed',
      numericEligible,
      construction,
      placement,
      previewCoverage,
      fullCoverage,
      geometry: smoke(field, preview, full, 0),
      previewGridSha256: hash(gridBytes(preview)),
      fullGridSha256: hash(gridBytes(full)),
      maskSha256: hash(mask),
      nativeImageSha256: hash(nativeImage),
      halfImageSha256: hash(halfImage),
      humanVisualDecision: 'pending',
      productionSelection: false,
    },
  };
}
async function main() {
  const mode = process.argv[2],
    target = process.argv[3];
  if (!['--local-gate', '--compare'].includes(mode) || !target)
    throw new Error('Use --local-gate NEW_DIRECTORY or --compare NEW_DIRECTORY.');
  const output = resolve(target);
  if (!output.startsWith(HERE) || output === HERE.slice(0, -1))
    throw new Error('Evidence must use a new revision directory inside issue-169.');
  await mkdir(output, { recursive: false });
  const sources = {};
  for (const file of [
    'experiment.md',
    'templates.mjs',
    'certificates.mjs',
    'geometry.mjs',
    'placement.mjs',
    'field.mjs',
    'run.mjs',
    '../issue-164/morphology.mjs',
    '../issue-164/render-comparison.mjs',
    '../issue-165/run.mjs',
    '../issue-164/comparison/results.json',
  ])
    sources[file] = hash(await readFile(join(HERE, file)));
  await json(join(output, 'manifest.json'), {
    revision: 'issue-169-r1',
    sources,
    inputs: await inputs(),
    kind: mode === '--compare' ? 'comparison' : 'local-certificate-gate',
  });
  const gate = await localGate();
  await json(join(output, 'local-gate.json'), gate);
  if (mode === '--local-gate' || !gate.completePrimaryPassed) {
    console.log(
      JSON.stringify({
        completePrimaryPassed: gate.completePrimaryPassed,
        constructionOk: gate.ok,
        failures: gate.failures,
      }),
    );
    return;
  }
  const reports = [];
  for (const input of await inputs()) {
    const first = render(input),
      repeat = render(input);
    assert.deepEqual(first, repeat);
    if (first.nativeImage) {
      await writeFile(join(output, `${input.id}.png`), first.nativeImage);
      await writeFile(join(output, `${input.id}-half.png`), first.halfImage);
    }
    reports.push({ ...first.report, exactRepeat: true });
    await json(join(output, `${input.id}.json`), reports.at(-1));
    console.log(`${input.id}: ${first.report.stage}`);
  }
  for (const [file, expected] of Object.entries(sources))
    assert.equal(
      hash(await readFile(join(HERE, file))),
      expected,
      `Source changed during run: ${file}`,
    );
  await json(join(output, 'results.json'), {
    revision: 'issue-169-r1',
    sources,
    reports,
    repeatScope: 'local process only; cross-platform equality unproved',
    editPolicy: 'immutable revision; retain failures; no human visual decisions inferred',
  });
}
if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) await main();

